/// Identify a file by its exact root namespace and relative UTF-8 path.
///
/// Full SHA-256 covers length-delimited components; the bounded ASCII prefix
/// is cosmetic. Callers canonicalize the root and reject non-UTF-8 paths before
/// use. Changing roots intentionally changes identities and requires migration.
/// The result leaves room for symbol/chunk/embedding suffixes under ArangoDB's
/// 254-byte document-key limit.
pub fn scoped_file_key(namespace: &str, rel_path: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(b"hades:file:v2\0");
    for component in [namespace, rel_path] {
        hasher.update((component.len() as u64).to_be_bytes());
        hasher.update(component.as_bytes());
    }
    let readable: String = rel_path
        .chars()
        .take(32)
        .map(|c| {
            if c.is_ascii_alphanumeric() || matches!(c, '_' | '-') {
                c
            } else {
                '_'
            }
        })
        .collect();
    let digest: String = hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    format!("f2_{readable}__{digest}")
}

/// Normalize a raw identifier into an ArangoDB document key.
///
/// 1. Strip trailing version suffix (`v1`, `v2`, etc.)
/// 2. Replace `.` and `/` with `_`
///
/// # Examples
/// ```
/// # use hades_core::db::keys::normalize_document_key;
/// assert_eq!(normalize_document_key("2501.12345v2"), "2501_12345");
/// assert_eq!(normalize_document_key("hep-th/9901001"), "hep-th_9901001");
/// ```
pub fn normalize_document_key(raw: &str) -> String {
    let stripped = VERSION_SUFFIX.replace(raw, "");
    stripped.replace(['.', '/'], "_")
}

/// Build a chunk key from a normalized document key and chunk index.
///
/// # Examples
/// ```
/// # use hades_core::db::keys::chunk_key;
/// assert_eq!(chunk_key("2501_12345", 3), "2501_12345_chunk_3");
/// ```
pub fn chunk_key(doc_key: &str, index: usize) -> String {
    format!("{doc_key}_chunk_{index}")
}

/// Build an embedding key from a chunk key.
///
/// # Examples
/// ```
/// # use hades_core::db::keys::embedding_key;
/// assert_eq!(embedding_key("2501_12345_chunk_3"), "2501_12345_chunk_3_emb");
/// ```
pub fn embedding_key(chunk_key: &str) -> String {
    format!("{chunk_key}_emb")
}

pub async fn create_vector_index(
    pool: &ArangoPool,
    collection: &str,
    field: &str,
    dimension: u32,
    n_lists: Option<u32>,
    n_probe: u32,
    metric: VectorMetric,
) -> Result<IndexInfo, ArangoError> {
    let n_lists = match n_lists {
        Some(n) => n,
        None => {
            // Auto-calculate from collection size
            let aql = format!("RETURN LENGTH({collection})");
            let result =
                query::query_single(pool, &aql, None, query::ExecutionTarget::Reader).await?;
            let doc_count = result.and_then(|v| v.as_u64()).unwrap_or(0);
            (doc_count / 15).max(1) as u32
        }
    };

    let encoded = encode_query_value(collection);
    let path = format!("index?collection={encoded}");
    let body = serde_json::json!({
        "type": "vector",
        "fields": [field],
        "params": {
            "metric": metric.as_str(),
            "dimension": dimension,
            "nLists": n_lists,
            "defaultNProbe": n_probe,
        },
    });

    debug!(
        collection,
        field,
        dimension,
        n_lists,
        n_probe,
        metric = metric.as_str(),
        "creating vector index"
    );

    let resp = pool.writer().post(&path, &body).await?;
    let info: IndexInfo = serde_json::from_value(resp)?;

    debug!(id = %info.id, "vector index created");
    Ok(info)
}

/// Find the first vector index on a collection and return its metric.
///
/// Returns `None` if no vector index exists.
pub async fn detect_vector_index(
    pool: &ArangoPool,
    collection: &str,
) -> Result<Option<VectorMetric>, ArangoError> {
    let indexes = list_indexes(pool, collection).await?;
    for idx in &indexes {
        if idx.index_type == "vector" {
            let metric = idx
                .params
                .as_ref()
                .and_then(|p| p.get("metric"))
                .and_then(|m| m.as_str())
                .unwrap_or("cosine");
            let vm = match metric {
                "l2" => VectorMetric::L2,
                "innerProduct" => VectorMetric::InnerProduct,
                _ => VectorMetric::Cosine,
            };
            return Ok(Some(vm));
        }
    }
    Ok(None)
}

pub async fn list_indexes(
    pool: &ArangoPool,
    collection: &str,
) -> Result<Vec<IndexInfo>, ArangoError> {
    let encoded = encode_query_value(collection);
    let path = format!("index?collection={encoded}");
    let resp = pool.reader().get(&path).await?;

    let indexes = resp
        .get("indexes")
        .and_then(|v| v.as_array())
        .ok_or_else(|| {
            ArangoError::Request("index list response missing 'indexes' array".to_string())
        })?;

    let mut result = Vec::with_capacity(indexes.len());
    for idx in indexes {
        let info: IndexInfo = serde_json::from_value(idx.clone())?;
        result.push(info);
    }

    debug!(collection, count = result.len(), "listed indexes");
    Ok(result)
}

/// Fold rows one page at a time, retaining cursor ownership after cancellation.
///
/// `guard` is retained through cleanup, including when the caller disappears or
/// the fold fails. Pass an admission permit here to keep abandoned requests
/// charged to their resource budget until their owner has finished.
/// Server streaming/memory options follow the AQL cursor HTTP API:
/// <https://docs.arango.ai/arangodb/stable/develop/http-api/queries/aql-queries/>.
pub async fn query_fold<T, F, G>(
    pool: &ArangoPool,
    aql: &str,
    bind_vars: Value,
    limits: FoldLimits,
    mut state: T,
    mut fold: F,
    guard: G,
) -> Result<T, ArangoError>
where
    T: Send + 'static,
    F: FnMut(&mut T, Value) -> Result<(), ArangoError> + Send + 'static,
    G: Send + 'static,
{
    if limits.batch_size == 0
        || limits.response_bytes == 0
        || limits.max_rows == 0
        || limits.server_memory_bytes == 0
    {
        return Err(ArangoError::Request(
            "streaming fold limits must be positive".into(),
        ));
    }
    let lifetime = QueryLimits::default();
    let body = serde_json::json!({
        "query": aql, "bindVars": bind_vars, "batchSize": limits.batch_size,
        "memoryLimit": limits.server_memory_bytes,
        "ttl": lifetime.cursor_ttl.as_secs_f64(),
        "options": {"stream": true, "maxRuntime": lifetime.lifetime.as_secs_f64()},
    });
    let client = if pool.is_shared() {
        pool.reader()
    } else {
        pool.writer()
    }
    .clone()
    .with_response_limit(limits.response_bytes)?;
    let (mut send, receive) = oneshot::channel();
    tokio::spawn(async move {
        let mut cursor = CursorOwner {
            client,
            ids: Vec::new(),
        };
        let result = tokio::time::timeout(lifetime.lifetime, async {
            if send.is_closed() {
                return Err(ArangoError::Request("query caller cancelled".into()));
            }
            // Shield creation so an available cursor ID survives caller loss.
            let mut response = cursor.client.post("cursor", &body).await?;
            let mut count = 0_u64;
            loop {
                cursor.observe(&response)?;
                if send.is_closed() {
                    return Err(ArangoError::Request("query caller cancelled".into()));
                }
                let more = has_more(&response)?;
                let rows = response.get_mut("result").and_then(Value::as_array_mut)
                    .ok_or_else(|| ArangoError::Request("cursor response missing result array".into()))?;
                count = count.checked_add(rows.len() as u64)
                    .filter(|count| *count <= limits.max_rows)
                    .ok_or_else(|| ArangoError::Request("streaming query row budget exceeded".into()))?;
                for row in std::mem::take(rows) {
                    if send.is_closed() {
                        return Err(ArangoError::Request("query caller cancelled".into()));
                    }
                    fold(&mut state, row)?;
                }
                if !more { break; }
                let id = cursor.ids.first().ok_or_else(||
                    ArangoError::Request("hasMore=true but no cursor ID in response".into()))?;
                let path = format!("cursor/{id}");
                let empty = serde_json::json!({});
                // Drop the old page before requesting another one.
                drop(response);
                response = tokio::select! {
                    biased;
                    _ = send.closed() => return Err(ArangoError::Request("query caller cancelled".into())),
                    response = cursor.client.post(&path, &empty) => response?,
                };
                // Cooperative yield also bounds cancellation latency for cached
                // responses and inexpensive folds on single-thread runtimes.
                tokio::task::yield_now().await;
            }
            Ok(state)
        })

async fn cleanup(self, budget: Duration) {
    let result = tokio::time::timeout(budget, async {
        for id in self.ids {
            if let Err(error) = self.client.delete(&format!("cursor/{id}")).await
                && !error.is_not_found()
            {
                tracing::warn!(%error, "cursor deletion failed; server TTL remains the fallback");
            }
        }
    }).await;
    if result.is_err() {
        tracing::warn!("cursor cleanup timed out; server TTL remains the fallback");
    }
}

fn observe(&mut self, response: &Value) -> Result<(), ArangoError> {
    let Some(value) = response.get("id") else {
        return Ok(());
    };
    let id = value
        .as_str()
        .filter(|id| {
            !id.is_empty()
                && id.len() <= 128
                && id
                    .bytes()
                    .all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-')
        })
        .ok_or_else(|| ArangoError::Request("invalid cursor ID".into()))?;
    if self.ids.first().is_some_and(|known| known != id) {
        self.ids.push(id.to_string());
        return Err(ArangoError::Request(
            "cursor ID changed during pagination".into(),
        ));
    }
    if self.ids.is_empty() {
        self.ids.push(id.to_string());
    }
    Ok(())
}

/// Remove every document in `collection` where ANY of `fields` equals `value`.
/// Returns the number of documents removed.
///
/// This is the single supported shape for field-match deletes. It exists
/// because the inlined versions kept reproducing the same two defects:
///
/// - **ArangoDB error 1552.** One bind map shared across two single-collection
///   queries declares a parameter the first query never uses, and ArangoDB
///   rejects declared-but-unused binds. That aborted every `--force` document
///   refresh (#169). Here each call builds exactly its own binds, so the
///   defect class is unrepresentable.
/// - **Field drift between writer and reader.** Field names arrive as data
///   (attribute-name binds, `d.@f`), so callers pass the same constants the
///   write path uses instead of re-typing them into query strings.
///   Attribute-name binds are resolved at parse time, before planning:
///   verified via `_api/explain` that `FILTER d.@f0 == @value` selects the
///   same persistent index (`IndexNode`, `fields=file_key`) as the literal
///   `FILTER d.file_key == @value`.
pub async fn remove_docs_by_fields(
    pool: &ArangoPool,
    collection: &str,
    fields: &[&str],
    value: &str,
) -> Result<u64, ArangoError> {
    if fields.is_empty() {
        return Err(ArangoError::Request(
            "remove_docs_by_fields: no fields given".to_string(),
        ));
    }
    // FILTER d.@f0 == @value OR d.@f1 == @value ...
    let filter = fields
        .iter()
        .enumerate()
        .map(|(i, _)| format!("d.@f{i} == @value"))
        .collect::<Vec<_>>()
        .join(" OR ");
    let aql = format!(
        "LET removed = (FOR d IN @@col FILTER {filter} REMOVE d IN @@col RETURN 1) \
         RETURN LENGTH(removed)"
    );
    let mut bind = serde_json::json!({ "@col": collection, "value": value });
    for (i, f) in fields.iter().enumerate() {
        bind[format!("f{i}")] = serde_json::json!(f);
    }
    let result = query_single(pool, &aql, Some(&bind), ExecutionTarget::Writer).await?;
    Ok(result.and_then(|v| v.as_u64()).unwrap_or(0))
}

/// Resolve the effective session tier from the transport policy and the
/// request's optional self-declared session.
///
/// Absent → the policy ceiling (admin locally, agent on the network).
/// `"agent"` → agent, always honored (self-restriction).
/// `"admin"` → admin only when the ceiling allows it; otherwise
/// `ACCESS_DENIED`, because silently downgrading an explicit claim would
/// misreport what tier the commands then run at.
pub fn resolve_session(
    policy: &ConnectionPolicy,
    requested: Option<SessionKind>,
    request_id: &Option<String>,
) -> Result<SessionKind, DaemonResponse> {
    match requested {
        None => Ok(policy.max_tier),
        Some(SessionKind::Agent) => Ok(SessionKind::Agent),
        Some(SessionKind::Admin) => match policy.max_tier {
            SessionKind::Admin => Ok(SessionKind::Admin),
            SessionKind::Agent => Err(DaemonResponse::err(
                "ACCESS_DENIED",
                "transport policy caps this connection at agent tier; \
                 admin session is not available on this endpoint",
            )
            .with_request_id(request_id.clone())),
        },
    }
}

/// Map a [`HandlerError`] to a protocol error code string.
pub fn handler_error_code(e: &HandlerError) -> &'static str {
    match e {
        HandlerError::InvalidNodeId { .. }
        | HandlerError::InvalidLimit { .. }
        | HandlerError::InvalidParameter { .. } => "INVALID_PARAMS",
        HandlerError::NodeNotFound(_) | HandlerError::DocumentNotFound { .. } => "NOT_FOUND",
        HandlerError::NoEmbedding { .. } | HandlerError::InvalidEmbedding { .. } => "QUERY_FAILED",
        // A query that failed because something was not there is a different
        // answer from a query that broke, and a caller surveying a graph needs
        // to tell them apart: "no such collection" ends the question, while
        // QUERY_FAILED invites a retry. Reported by one session as turning a
        // single question into six probes to establish a negative.
        HandlerError::Query { source, .. } if source.is_not_found() => "NOT_FOUND",
        HandlerError::Query { .. } => "QUERY_FAILED",
        HandlerError::SearchOverloaded => "SEARCH_OVERLOADED",
        HandlerError::ServiceError(_) => "SERVICE_ERROR",
    }
}

/// Validate `db.query`'s `limit`, rejecting rather than clamping.
///
/// `0` is rejected because `0.min(MAX_LIMIT)` is `0`: the search returned
/// `{"success": true, "result_count": 0}`, which an agent cannot tell apart from
/// "nothing matched", so it retries with new phrasings against a limit that can
/// never return anything. That is the turn-burning ambiguity #187 exists to
/// remove, arriving through a different door.
///
/// Above `MAX_LIMIT` is rejected rather than clamped because the pre-#187 CLI
/// honoured whatever `-n` was passed. Clamping would silently return exactly
/// 1000 rows with nothing in the JSON envelope or on stderr saying the result
/// had been truncated, which is the same class of quiet misreport.
fn validated_query_limit(limit: Option<u32>) -> Result<u32, HandlerError> {
    let limit = limit.unwrap_or(10);
    if limit == 0 || limit > MAX_LIMIT {
        return Err(HandlerError::InvalidLimit {
            limit,
            max: MAX_LIMIT,
        });
    }
    Ok(limit)
}

/// Blend vector similarity with keyword term coverage:
/// `0.7 * vector + 0.3 * keyword`, then re-sort.
fn hybrid_rerank(query_text: &str, mut results: Vec<Value>) -> Vec<Value> {
    let query_terms = tokenize(query_text);
    if query_terms.is_empty() {
        return results;
    }

    for result in &mut results {
        let vector_score = result["score"].as_f64().unwrap_or(0.0);
        let text = result["text"].as_str().unwrap_or("");
        let keyword_score = keyword_tf_score(&query_terms, text);

        result["vector_score"] = json!(vector_score);
        result["keyword_score"] = json!(keyword_score);
        result["score"] = json!(0.7 * vector_score + 0.3 * keyword_score);
    }

    results.sort_by(|a, b| {
        let sa = a["score"].as_f64().unwrap_or(0.0);
        let sb = b["score"].as_f64().unwrap_or(0.0);
        sb.partial_cmp(&sa).unwrap_or(std::cmp::Ordering::Equal)
    });

    results
}

